<?php require 'config/config.php';$s=db()->prepare("SELECT r.*,p.title,p.address,p.city,p.description,u.name owner FROM rooms r JOIN properties p ON p.id=r.property_id JOIN users u ON u.id=p.owner_id WHERE r.id=?");$s->execute([(int)$_GET['id']]);$r=$s->fetch();if(!$r)exit('Room not found');$title=$r['title'];require 'config/header.php';?><div class="detail"><div><div class="photo big"></div><div class="panel"><small><?=e($r['city'])?></small><h1><?=e($r['title'])?></h1><p><?=e($r['description'])?></p><p><?=e($r['address'])?></p><p>Room <?=e($r['room_number'])?> · <?=e($r['room_type'])?></p></div></div><aside class="panel"><strong class="bigprice"><?=money($r['rent'])?></strong><p>/ month</p><p>Advance: <b><?=money($r['deposit'])?></b></p><?php if($r['status']==='available'):?><a class="btn" href="<?=BASE_URL?>/booking.php?room_id=<?=$r['id']?>">Book this room</a><?php else:?><b>Occupied</b><?php endif;?></aside></div><?php require 'config/footer.php';?>
